<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowDown, ArrowRight, Check, Close, Clock, Connection, Cpu, DataLine, Delete, Files, Lock, Monitor, Operation, Plus, Refresh, Setting, VideoPause, VideoPlay } from '@element-plus/icons-vue'
import { api } from './api'
import { canCreateDomain, domainStatusClass as policyDomainStatusClass, mappingStatusClass } from './policy'
import { useClientStore, type CertificateInfo, type Domain, type Mapping, type Operation as ClientOperation } from './stores/client'

const store = useClientStore()
const view = ref('tunnels')
const showAddress = ref(false)
const showCreate = ref(false)
const showDomain = ref(false)
const editing = ref<Mapping | null>(null)
const saving = ref(false)
const domainSaving = ref(false)
const inspecting = ref(false)
const certificate = ref<CertificateInfo | null>(null)
const form = ref({ name: '', proxy_type: 'tcp' as 'tcp' | 'udp' | 'http', local_ip: '127.0.0.1', local_port: 8080, remote_port: 0 })
const domainForm = ref({ mapping_id: '', hostname: '', https_mode: 'auto_certificate', http_redirect: true, dns_type: 'CNAME' as 'A' | 'AAAA' | 'CNAME', dns_content: '', dns_ttl: 300 })
const login = ref({ server_panel_url: localStorage.getItem('last_server_panel_url') || '', username: '', password: '' })
const nav = [
  { id: 'tunnels', label: '我的隧道', kicker: 'TUNNELS', icon: Connection },
  { id: 'domains', label: '业务域名', kicker: 'DOMAIN BINDINGS', icon: Connection },
  { id: 'local', label: '本地运行', kicker: 'LOCAL RUNTIME', icon: DataLine },
  { id: 'operations', label: '操作队列', kicker: 'OPERATIONS', icon: Operation },
  { id: 'logs', label: '脱敏日志', kicker: 'SANITIZED LOGS', icon: Files },
]
const activeNav = computed(() => nav.find(item => item.id === view.value) ?? nav[0])
const supervisor = computed(() => store.localStatus as { state?: string; mode?: string; pid?: number; desired_config_version?: number; applied_config_version?: number; last_good_available?: boolean; last_error?: string })
const live = computed(() => supervisor.value.state === 'running')
const httpMappings = computed(() => store.dashboard?.mappings.filter(item => item.proxy_type === 'http' && item.lifecycle_status !== 'deleted') ?? [])

function resetForm() { editing.value = null; form.value = { name: '', proxy_type: 'tcp', local_ip: '127.0.0.1', local_port: 8080, remote_port: 0 } }
function openCreate() { resetForm(); showCreate.value = true }
function openEdit(item: Mapping) { editing.value = item; form.value = { name: item.name, proxy_type: item.proxy_type, local_ip: item.local_ip, local_port: item.local_port, remote_port: item.remote_port ?? 0 }; showCreate.value = true }
function openDomain() { if (!canCreateDomain(httpMappings.value.length)) return; domainForm.value = { mapping_id: httpMappings.value[0]?.id ?? '', hostname: '', https_mode: 'auto_certificate', http_redirect: true, dns_type: 'CNAME', dns_content: '', dns_ttl: 300 }; showDomain.value = true }
async function completePasswordChange(currentPassword?: string) { const current = currentPassword ?? (await ElMessageBox.prompt('请输入当前密码完成重新认证。', '修改登录密码', { inputType: 'password', inputPlaceholder: '当前密码', confirmButtonText: '继续', cancelButtonText: '取消', inputValidator: value => Boolean(value?.trim()) || '请输入当前密码' })).value; const next = await ElMessageBox.prompt('首次登录必须设置新密码，至少 12 个字符。', '设置新密码', { inputType: 'password', inputPlaceholder: '新密码（至少 12 个字符）', confirmButtonText: '下一步', cancelButtonText: '取消', inputValidator: value => (value?.length ?? 0) >= 12 || '新密码至少需要 12 个字符' }); const confirmation = await ElMessageBox.prompt('再次输入新密码完成确认。', '确认新密码', { inputType: 'password', inputPlaceholder: '再次输入新密码', confirmButtonText: '保存密码', cancelButtonText: '取消', inputValidator: value => Boolean(value?.trim()) || '请输入确认密码' }); if (next.value !== confirmation.value) throw new Error('两次新密码不一致'); await store.changePassword(current, next.value); login.value.password = ''; ElMessage.success('密码已更新，请继续同步配置') }
async function requirePasswordChange(currentPassword?: string) { if (!store.user?.must_change_password) return true; try { await completePasswordChange(currentPassword); return true } catch (err) { await store.logout(); if (err === 'cancel') ElMessage.warning('必须完成首次改密后才能使用 Client Panel'); else ElMessage.error(err instanceof Error ? err.message : '首次改密失败'); return false } }
async function inspectServer() { inspecting.value = true; certificate.value = null; try { certificate.value = await store.inspectServer(login.value.server_panel_url); ElMessage.success(certificate.value.verified ? '证书已通过系统信任校验' : '证书信息已获取，请核对指纹后决定是否信任') } catch (err) { store.error = err instanceof Error ? err.message : '证书检查失败' } finally { inspecting.value = false } }
async function submitLogin() { try { let trustedSPKI = ''; if (certificate.value && !certificate.value.verified) { await ElMessageBox.confirm(`请核对证书主题、有效期和 SPKI 指纹：\n${certificate.value.spki_sha256 || '不可用'}\n\n确认后才会发送登录密码。指纹变化将阻止后续请求。`, '高风险证书信任', { type: 'warning', confirmButtonText: '确认并继续', cancelButtonText: '返回' }); trustedSPKI = certificate.value.spki_sha256 || '' } await store.login({ ...login.value, ...(trustedSPKI ? { trusted_spki_sha256: trustedSPKI } : {}) }); if (!(await requirePasswordChange(login.value.password))) return; await store.refresh(); ElMessage.success('已连接 Server Panel') } catch (err) { if (err !== 'cancel') store.error = err instanceof Error ? err.message : '登录失败' } }
async function retryOperation(operation: ClientOperation) { try { await store.retryOperation(operation.id); ElMessage.success('操作已重新入队') } catch (err) { ElMessage.error(err instanceof Error ? err.message : '重试失败') } }
async function resetFRPCredential() { try { const prompt = await ElMessageBox.prompt('输入当前 Server Panel 密码确认。重置后当前 FRP 运行凭证和 Client Session 会立即失效，需要重新登录。', '重置 FRP 凭证', { inputType: 'password', inputPlaceholder: '当前密码', confirmButtonText: '确认重置', cancelButtonText: '取消', inputValidator: value => Boolean(value?.trim()) || '请输入当前密码' }); await store.resetFRPCredential(prompt.value); ElMessage.success('FRP 凭证已重置，请重新登录') } catch (err) { if (err !== 'cancel') ElMessage.error(err instanceof Error ? err.message : 'FRP 凭证重置失败') } }
async function saveMapping() { saving.value = true; try { const body = { ...form.value, remote_port: form.value.proxy_type === 'http' ? null : (form.value.remote_port || null), expected_config_version: store.dashboard?.desired_config_version, expected_revision: editing.value?.revision }; const path = editing.value ? `/api/v1/mappings/${editing.value.id}` : '/api/v1/mappings'; await api(path, { method: editing.value ? 'PUT' : 'POST', body: JSON.stringify(body) }); showCreate.value = false; resetForm(); await store.refresh(); ElMessage.success(editing.value ? 'Mapping 已提交新 Revision' : 'Mapping 已保留端口并等待应用') } catch (err) { ElMessage.error(err instanceof Error ? err.message : '保存失败') } finally { saving.value = false } }
async function saveDomain() { domainSaving.value = true; try { await api('/api/v1/domains', { method: 'POST', body: JSON.stringify({ ...domainForm.value, expected_config_version: store.dashboard?.desired_config_version }) }); showDomain.value = false; await store.refresh(); ElMessage.success('Domain Binding 已创建，等待 DNS / Router / Client 应用') } catch (err) { ElMessage.error(err instanceof Error ? err.message : '域名创建失败') } finally { domainSaving.value = false } }
async function toggle(item: Mapping) { try { await api(`/api/v1/mappings/${item.id}/toggle`, { method: 'POST', body: JSON.stringify({ enabled: item.desired_state !== 'enabled', expected_config_version: store.dashboard?.desired_config_version, expected_revision: item.revision }) }); await store.refresh() } catch (err) { ElMessage.error(err instanceof Error ? err.message : '操作失败') } }
async function remove(item: Mapping) { try { await ElMessageBox.confirm('删除会先标记为 deleting，等待 Client 应用后释放资源。', '确认删除 Mapping', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await api(`/api/v1/mappings/${item.id}`, { method: 'DELETE' }); await store.refresh(); ElMessage.success('删除操作已进入队列') } catch { /* cancelled */ } }
async function removeDomain(item: Domain) { try { await ElMessageBox.confirm('删除 Domain Binding 会进入可重试的清理流程；外部 DNS 是否删除由 managed 状态决定。', '确认删除 Domain Binding', { type: 'warning', confirmButtonText: '删除域名', cancelButtonText: '取消' }); await api(`/api/v1/domains/${item.id}`, { method: 'DELETE' }); await store.refresh(); ElMessage.success('域名删除操作已进入队列') } catch { /* cancelled */ } }
async function resolveDNS(item: Domain, action: 'adopt' | 'overwrite' | 'cancel' | 'sync') { try { await ElMessageBox.confirm(action === 'adopt' ? '仅接管现有记录，删除时不会删除该外部 DNS。' : action === 'overwrite' ? '覆盖现有记录，并将该记录标记为面板管理。' : action === 'sync' ? '只更新已经由面板管理的 DNS 记录，不会修改外部接管记录。' : '取消本次 DNS 操作。', '确认 DNS 操作', { type: action === 'overwrite' ? 'warning' : 'info', confirmButtonText: '继续', cancelButtonText: '返回' }); await api(`/api/v1/domains/${item.id}/dns-action`, { method: 'POST', body: JSON.stringify({ action }) }); await store.refresh(); ElMessage.success('DNS 处理已重新进入队列') } catch { /* cancelled */ } }
function statusLabel(status: string) { return ({ running: '运行中', pending_apply: '等待应用', reserved: '资源已保留', offline: '离线', config_error: '配置错误', disabled: '已停用', deleting: '删除中' } as Record<string, string>)[status] ?? status }
function statusClass(status: string) { return mappingStatusClass(status) }
function domainStatusClass(status: string) { return policyDomainStatusClass(status) }
function domainStatusLabel(status: string) { return ({ pending_dns: '等待 DNS', dns_error: 'DNS 错误', pending_certificate: '等待证书', certificate_error: '证书错误', pending_router: '等待 Router', pending_client: '等待 Client', router_error: 'Router 错误', pending_apply: '等待应用', active: '已激活', offline: '离线', deleting: '删除中' } as Record<string, string>)[status] ?? status }
function domainModeLabel(mode: string) { return ({ auto_certificate: '自动证书', cloudflare_proxy: 'Cloudflare 代理', http_only: '仅 HTTP' } as Record<string, string>)[mode] ?? mode }
function dnsSummary(item: Domain) { return `${item.dns_type} ${item.dns_content || 'pending'} · TTL ${item.dns_ttl}${item.dns_proxied ? ' · 小橙云' : ' · DNS only'}` }
function mappingName(id: string) { return httpMappings.value.find(item => item.id === id)?.name ?? 'HTTP Mapping' }
function endpoint(item: Mapping) { return item.proxy_type === 'http' ? 'Domain Binding pending' : `${store.dashboard ? 'FRPS public endpoint' : 'remote'}:${item.remote_port || 'auto'}` }
function formatTime(value: string) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '—' }
function operationStatusLabel(status: string) { return ({ pending: '等待执行', running: '执行中', retry_wait: '等待重试', succeeded: '已完成', failed: '失败', canceled: '已取消' } as Record<string, string>)[status] ?? status }
function operationStatusClass(status: string) { return ['succeeded', 'running', 'pending', 'retry_wait', 'failed', 'canceled'].includes(status) ? status : 'pending' }
watch(() => login.value.server_panel_url, () => { certificate.value = null })
watch(() => domainForm.value.https_mode, mode => { if (mode === 'http_only') domainForm.value.http_redirect = false })
onMounted(async () => { await store.restore(); if (store.authenticated && await requirePasswordChange()) await store.refresh() })
</script>

<template>
  <div v-if="store.loading" class="boot"><div class="boot-mark">FRP<span>/</span>CLIENT</div><div class="boot-line">warming local runtime</div></div>
  <div v-else-if="!store.authenticated" class="login-shell"><div class="login-visual"><div class="brand"><span class="brand-dot"></span><span>FRP / CLIENT</span></div><div class="visual-grid"></div><div class="login-stamp"><span class="eyebrow">LOCAL CONTROL SURFACE</span><h1>你的服务，<br><em>你的边界。</em></h1><p>Client Panel 是本地常驻服务。它不创建本地用户，也不保存 Server Session；所有资源权威来自你选择的 Server Panel。</p><div class="feature-line"><Connection :size="15" /> SINGLE ACTIVE CLIENT SESSION</div><div class="feature-line"><Lock :size="15" /> RUNTIME SECRETS / MEMORY ONLY</div></div><div class="rail-foot"><span class="live-dot amber-dot"></span>LOCAL PANEL / v0.1.0</div></div><main class="login-main"><div class="login-top"><span>CLIENT PANEL LOGIN</span><span class="top-meta">LOCAL HTTP · SESSION IN MEMORY</span></div><form class="login-card" @submit.prevent="submitLogin"><div class="section-number">01 <span>CONNECT TO SERVER</span></div><h2>开始连接。</h2><p class="muted">使用 Server Panel 用户账号登录。新登录会替换同一账号已有的 Client Session。</p><label>用户名<input v-model="login.username" autocomplete="username" required></label><label>密码<input v-model="login.password" type="password" autocomplete="current-password" required></label><button class="primary-button" type="submit">登录并同步配置 <ArrowDown :size="16" class="rotate-45" /></button><button class="address-toggle" type="button" @click="showAddress = !showAddress"><ArrowRight :size="15" :class="{ expanded: showAddress }" />配置 Server Panel 连接地址</button><div v-if="showAddress" class="address-reveal"><label>Server Panel 连接地址<input v-model="login.server_panel_url" placeholder="https://panel.example.com:8443" autocomplete="url"><small>生产环境必须使用 HTTPS；支持域名、IPv4 和方括号 IPv6。</small></label><div class="certificate-tools"><button class="text-button" type="button" :disabled="inspecting || !login.server_panel_url" @click="inspectServer">{{ inspecting ? '检查中…' : '检查证书 / 查看 SPKI 指纹' }}</button><span class="certificate-hint">密码发送前可先完成证书核对。</span></div><div v-if="certificate" class="certificate-card" :class="{ trusted: certificate.verified, warning: !certificate.verified }"><div class="certificate-title"><strong>{{ certificate.verified ? '系统信任证书' : '需要显式信任' }}</strong><span>{{ certificate.transport.toUpperCase() }}</span></div><div>主题：{{ certificate.subject || '—' }}</div><div>有效期：{{ certificate.not_before ? formatTime(certificate.not_before) : '—' }} → {{ certificate.not_after ? formatTime(certificate.not_after) : '—' }}</div><div class="mono">SPKI：{{ certificate.spki_sha256 || '—' }}</div><small>{{ certificate.verified ? '连接可使用系统 CA 验证。' : (certificate.verification_error || '未通过系统 CA 验证；确认指纹后才会发送密码。') }}</small></div></div><p v-if="store.error" class="error-text"><Close :size="15" />{{ store.error }}</p><div class="login-note"><Lock :size="14" /> Server Session 只在 Client 内存中维护。浏览器 localStorage 只保存非敏感的上次 Server 地址。</div></form></main></div>
  <div v-else class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-dot"></span><span>FRP / CLIENT</span></div><div class="side-caption">LOCAL FRPC SUPERVISOR</div><nav><button v-for="item in nav" :key="item.id" :class="['nav-item', { active: view === item.id }]" @click="view = item.id"><component :is="item.icon" :size="17" /><span><small>{{ item.kicker }}</small>{{ item.label }}</span><i v-if="view === item.id"></i></button></nav><div class="sidebar-bottom"><div class="server-pill"><span :class="['state-dot', { live: live }]" /><div><small>SERVER PANEL</small><strong>{{ store.serverURL }}</strong></div></div><button class="profile" @click="store.logout"><span class="avatar">{{ store.user?.username?.slice(0, 1).toUpperCase() }}</span><span><strong>{{ store.user?.username }}</strong><small>普通用户 · 退出</small></span><ArrowDown :size="16" class="profile-arrow" /></button></div></aside><main class="content"><header class="content-header"><div><div class="breadcrumb">CLIENT PANEL <span>/</span> {{ activeNav.kicker }}</div><h1>{{ activeNav.label }}</h1></div><div class="header-actions"><span class="sync-state"><span :class="['live-dot', { offline: !live }]" />{{ live ? 'FRPC · RUNNING' : 'FRPC · ' + (supervisor.state || 'OFFLINE').toUpperCase() }}</span><button class="icon-button" aria-label="同步" @click="store.refresh"><Refresh :size="17" /></button></div></header>
      <section v-if="view === 'tunnels'" class="view"><div class="hero-strip"><div><span class="eyebrow">DESIRED / OBSERVED STATE</span><h2>把服务带到外面<span class="accent-dot">.</span></h2><p>Server 先保留资源，Client 再校验本地服务并应用配置。</p></div><div class="hero-code"><span>APPLIED VERSION</span><strong>{{ store.dashboard?.applied_config_version ?? 0 }} <small>/ {{ store.dashboard?.desired_config_version ?? 0 }}</small></strong><small>desired / applied</small></div></div><div class="metric-grid"><article class="metric"><div class="metric-label"><Connection :size="15" /> TOTAL MAPPINGS</div><strong>{{ store.dashboard?.counts.total_mappings ?? 0 }}</strong><span class="metric-note">归属于当前用户</span></article><article class="metric"><div class="metric-label"><VideoPlay :size="15" /> RUNNING</div><strong>{{ store.dashboard?.counts.running ?? 0 }}</strong><span class="metric-note green">observed by Client</span></article><article class="metric"><div class="metric-label"><Clock :size="15" /> PENDING</div><strong>{{ store.dashboard?.counts.pending ?? 0 }}</strong><span class="metric-note amber">resource or apply pending</span></article><article class="metric"><div class="metric-label"><Cpu :size="15" /> SUPERVISOR</div><strong class="small-metric">{{ supervisor.mode === 'real' ? 'REAL' : 'DEV' }}</strong><span class="metric-note">single operation queue</span></article></div><div class="toolbar"><div><span class="eyebrow">USER MAPPINGS</span><p class="view-intro">TCP、UDP 和 HTTP 是唯一的业务类型。端口与域名的最终占用由 Server 数据库决定。</p></div><button class="primary-button compact" @click="openCreate"><Plus :size="16" /> 新建 Mapping</button></div><section class="mapping-list"><article v-for="item in store.dashboard?.mappings ?? []" :key="item.id" class="mapping-row"><div class="mapping-type" :class="item.proxy_type"><span>{{ item.proxy_type.toUpperCase() }}</span><small>REV {{ item.revision }}</small></div><div class="mapping-main"><div class="mapping-title"><h3>{{ item.name }}</h3><span :class="['status', statusClass(item.lifecycle_status)]">{{ statusLabel(item.lifecycle_status) }}</span></div><div class="mapping-detail"><span><strong>{{ item.local_ip }}:{{ item.local_port }}</strong> local target</span><span class="arrow-line">→</span><span><strong>{{ endpoint(item) }}</strong></span></div><div class="mapping-meta"><span>desired: {{ item.desired_state }}</span><span>observed: {{ item.observed_state }}</span><span>updated revision: {{ item.revision }}</span></div></div><div class="mapping-actions"><button class="icon-button" :aria-label="item.desired_state === 'enabled' ? '停用' : '启用'" @click="toggle(item)"><VideoPause v-if="item.desired_state === 'enabled'" :size="16" /><VideoPlay v-else :size="16" /></button><button class="icon-button" aria-label="编辑" @click="openEdit(item)"><Setting :size="16" /></button><button class="icon-button danger-icon-button" aria-label="删除" @click="remove(item)"><Delete :size="16" /></button></div></article><div v-if="!store.dashboard?.mappings.length" class="empty-state"><div class="empty-mark"><Plus :size="18" /></div><h3>还没有 Mapping</h3><p>先定义一个本地目标服务。创建后 Server 会保留端口，Client 会在应用成功后变成 running。</p><button class="text-button" @click="openCreate">创建第一个 Mapping <ArrowDown :size="14" class="rotate-45" /></button></div></section></section>
      <section v-else-if="view === 'domains'" class="view"><div class="local-header"><div><span class="eyebrow">HTTP MAPPING / DOMAIN BINDING</span><h2>业务域名</h2><p class="view-intro">Domain Binding 绑定到已有 HTTP Mapping；DNS、证书、Router 与 Client 应用按 Operation 分步推进。</p></div><button class="primary-button compact" :disabled="!httpMappings.length" @click="openDomain"><Plus :size="16" /> 新建域名</button></div><div class="domain-summary"><span><strong>{{ store.domains.length }}</strong> bindings</span><span><strong>{{ store.domains.filter(item => item.status === 'active').length }}</strong> active</span><span class="amber"><strong>{{ store.domains.filter(item => item.status !== 'active').length }}</strong> pending / blocked</span></div><section class="domain-list"><article v-for="item in store.domains" :key="item.id" class="domain-card"><div class="domain-main"><div class="domain-title"><h3>{{ item.hostname }}</h3><span :class="['status', domainStatusClass(item.status)]">{{ domainStatusLabel(item.status) }}</span></div><div class="domain-meta"><span>{{ mappingName(item.mapping_id) }}</span><span>{{ domainModeLabel(item.https_mode) }}</span><span>{{ dnsSummary(item) }}</span><span>{{ item.dns_managed_by_panel ? '面板管理' : item.dns_adopted ? '外部接管' : '未同步' }}</span><span>{{ item.http_redirect ? 'HTTP → HTTPS' : 'no redirect' }}</span></div><small class="mono">normalized: {{ item.normalized_domain }} · revision {{ item.revision }}</small><div v-if="item.status === 'dns_error'" class="domain-actions"><button class="text-button" @click="resolveDNS(item, 'adopt')">仅添加 / 接管</button><button class="text-button" @click="resolveDNS(item, 'overwrite')">覆盖记录</button><button class="text-button" @click="resolveDNS(item, 'cancel')">取消</button></div><div v-if="item.dns_managed_by_panel && item.status === 'active'" class="domain-actions"><button class="text-button" @click="resolveDNS(item, 'sync')">一键同步 DNS</button></div></div><div class="domain-actions"><button class="icon-button" aria-label="删除域名" @click="removeDomain(item)"><Delete :size="16" /></button></div></article><div v-if="!store.domains.length" class="empty-state"><div class="empty-mark"><Connection :size="18" /></div><h3>还没有 Domain Binding</h3><p>先创建一个 proxy type 为 HTTP 的 Mapping，再为它绑定业务域名。</p><button class="text-button" :disabled="!httpMappings.length" @click="openDomain">绑定第一个域名 <ArrowDown :size="14" class="rotate-45" /></button></div></section></section>
      <section v-else-if="view === 'local'" class="view"><div class="local-header"><div><span class="eyebrow">PROCESS / CONFIG / HEALTH</span><h2>本地运行状态</h2><p class="view-intro">配置操作全部经过同一个 Supervisor 队列。无有效 Server Session 时，FRPC 会停止，运行时秘密会清除。</p></div><div :class="['runtime-badge', { live }]"><span class="state-dot" :class="{ live }"></span><strong>{{ supervisor.state || 'stopped' }}</strong><small>{{ supervisor.mode || 'simulated' }}</small></div></div><div class="local-grid"><section class="panel local-card"><div class="panel-head"><div><span class="eyebrow">SUPERVISOR</span><h3>进程与配置</h3></div><Monitor :size="20" /></div><div class="local-row"><span>Mode</span><strong>{{ supervisor.mode || 'simulated' }}</strong></div><div class="local-row"><span>PID</span><strong>{{ supervisor.pid || '—' }}</strong></div><div class="local-row"><span>Desired config</span><strong>{{ supervisor.desired_config_version ?? 0 }}</strong></div><div class="local-row"><span>Applied config</span><strong>{{ supervisor.applied_config_version ?? 0 }}</strong></div><div class="local-row"><span>Rollback file</span><strong :class="supervisor.last_good_available ? 'green' : 'amber'">{{ supervisor.last_good_available ? 'available' : 'not yet' }}</strong></div><button class="primary-button compact sync-button" @click="store.refresh"><Refresh :size="15" /> 重新读取状态</button></section><section class="panel local-card"><div class="panel-head"><div><span class="eyebrow">RECONCILIATION</span><h3>期望 vs 实际</h3></div><Check :size="20" class="ok-icon" /></div><div class="reconcile"><div><span>Server desired</span><strong>{{ store.dashboard?.desired_config_version ?? 0 }}</strong></div><div class="reconcile-line"></div><div><span>Client applied</span><strong>{{ store.dashboard?.applied_config_version ?? 0 }}</strong></div></div><p class="form-hint">版本不一致时，Client 会全量拉取签名快照；WebSocket 只负责通知，不能替代全量同步。</p><p v-if="supervisor.last_error" class="error-box">{{ supervisor.last_error }}</p></section></div></section>
      <section v-else-if="view === 'operations'" class="view"><div class="local-header"><div><span class="eyebrow">DURABLE SERVER OPERATIONS</span><h2>操作队列</h2><p class="view-intro">每个异步操作都展示当前阶段、失败原因、外部残留和可重试入口。离线时只读显示最近一次缓存。</p></div><button class="primary-button compact" @click="store.refresh"><Refresh :size="15" /> 刷新队列</button></div><section class="panel panel-table operation-table"><table><thead><tr><th>类型</th><th>阶段 / 步骤</th><th>状态</th><th>结果</th><th>时间</th><th>动作</th></tr></thead><tbody><tr v-for="operation in store.operations" :key="operation.id"><td><strong>{{ operation.operation_type }}</strong><small class="mono">{{ operation.resource_type }} · {{ operation.id.slice(0, 12) }}</small></td><td>{{ operation.phase }} / {{ operation.step }}<small v-if="operation.external_residue_count">外部残留：{{ operation.external_residue_count }} 项</small></td><td><span :class="['status', operationStatusClass(operation.status)]">{{ operationStatusLabel(operation.status) }}</span></td><td><small v-if="operation.error_code" class="error-text compact-error">{{ operation.error_code }} · {{ operation.error_message }}</small><small v-else>{{ operation.compensation_status || '—' }}</small></td><td class="muted">{{ formatTime(operation.created_at) }}</td><td><button v-if="['failed', 'canceled'].includes(operation.status)" class="text-button" @click="retryOperation(operation)">重试</button><span v-else class="muted">—</span></td></tr><tr v-if="!store.operations.length"><td colspan="6" class="empty">当前没有异步操作记录。</td></tr></tbody></table></section></section>
      <section v-else class="view"><div class="local-header"><div><span class="eyebrow">SANITIZED LOCAL TELEMETRY</span><h2>脱敏日志</h2><p class="view-intro">日志不会展示密码、Cookie、Authorization、Cloudflare Token、FRP Secret 或证书私钥。</p></div></div><section class="panel log-panel"><div class="log-line"><span class="log-time">{{ new Date().toLocaleTimeString('zh-CN', { hour12: false }) }}</span><span class="log-level">INFO</span><span>Supervisor status snapshot is available.</span></div><div class="log-line"><span class="log-time">{{ new Date(Date.now() - 24000).toLocaleTimeString('zh-CN', { hour12: false }) }}</span><span class="log-level">INFO</span><span>Last-good manifest is protected from partial writes.</span></div><div class="log-line"><span class="log-time">{{ new Date(Date.now() - 58000).toLocaleTimeString('zh-CN', { hour12: false }) }}</span><span class="log-level">INFO</span><span>Server Session remains memory-only.</span></div></section></section>
    <section v-if="view === 'local'" class="panel local-card credential-panel"><div class="panel-head"><div><span class="eyebrow">CREDENTIAL LIFECYCLE</span><h3>重置 FRP 凭证</h3></div><Lock :size="20" /></div><p class="form-hint">状态：{{ store.dashboard?.frp_credential.status ?? 'unknown' }} · Secret Version：v{{ store.dashboard?.frp_credential.secret_version ?? 0 }} · 最近重置：{{ store.dashboard?.frp_credential.rotated_at ? formatTime(store.dashboard.frp_credential.rotated_at) : '未重置' }}。完成当前密码二次认证后生成新 Secret。旧 FRP 连接、旧 Session 和旧 generation 会立即失效；新 Secret 不会在界面展示。</p><button class="text-button danger" @click="resetFRPCredential">重置 FRP 凭证并退出</button></section></main><el-dialog v-model="showCreate" :title="editing ? '创建新 Revision' : '新建 Mapping'" width="520px" class="dark-dialog"><div class="form-grid"><label>名称<input v-model="form.name" placeholder="例如: home-dashboard"></label><label>类型<select v-model="form.proxy_type"><option value="tcp">TCP / IP+端口</option><option value="udp">UDP / IP+端口</option><option value="http">HTTP / 域名</option></select></label><label>本地目标地址<input v-model="form.local_ip" placeholder="127.0.0.1"></label><label>本地目标端口<input v-model.number="form.local_port" type="number" min="1" max="65535"></label><label v-if="form.proxy_type !== 'http'">远程端口<input v-model.number="form.remote_port" type="number" min="0" max="65535" placeholder="0 = 自动分配"></label></div><p class="form-hint">提交后先由 Server 创建不可变 Revision 与 Port Lease；Client 校验 `frpc verify` 成功后才会显示 running。</p><template #footer><button class="text-button" @click="showCreate = false">取消</button><button class="primary-button compact" :disabled="saving" @click="saveMapping">{{ saving ? '提交中…' : editing ? '提交新 Revision' : '创建并应用' }}</button></template></el-dialog><el-dialog v-model="showDomain" title="新建 Domain Binding" width="560px" class="dark-dialog"><div class="form-grid"><label>绑定 HTTP Mapping<select v-model="domainForm.mapping_id" required><option v-for="mapping in httpMappings" :key="mapping.id" :value="mapping.id">{{ mapping.name }} · {{ mapping.local_ip }}:{{ mapping.local_port }}</option></select></label><label>业务域名<input v-model="domainForm.hostname" placeholder="app.example.com" autocomplete="off"></label><label>HTTPS 模式<select v-model="domainForm.https_mode"><option value="auto_certificate">自动证书</option><option value="cloudflare_proxy">Cloudflare 代理</option><option value="http_only">仅 HTTP</option></select></label><label>DNS 记录类型<select v-model="domainForm.dns_type"><option value="CNAME">CNAME · 指向 FRPS Host</option><option value="A">A · IPv4</option><option value="AAAA">AAAA · IPv6</option></select></label><label>DNS 内容<input v-model="domainForm.dns_content" :placeholder="domainForm.dns_type === 'CNAME' ? '留空使用 FRPS 公网 Host' : domainForm.dns_type === 'A' ? '203.0.113.10' : '2001:db8::10'" autocomplete="off"></label><label>TTL（秒）<input v-model.number="domainForm.dns_ttl" type="number" min="60" max="86400"></label><label class="checkbox-label"><span>HTTP → HTTPS</span><input v-model="domainForm.http_redirect" type="checkbox" :disabled="domainForm.https_mode === 'http_only'"></label></div><p class="form-hint">记录类型、内容和 TTL 会进入 DNS Operation；proxied 由 HTTPS 模式决定：Cloudflare 代理使用小橙云，其余模式为 DNS only。</p><template #footer><button class="text-button" @click="showDomain = false">取消</button><button class="primary-button compact" :disabled="domainSaving || !domainForm.mapping_id || !domainForm.hostname" @click="saveDomain">{{ domainSaving ? '提交中…' : '创建并进入队列' }}</button></template></el-dialog></div>
</template>
